245|static int
246|yaml_parser_state_machine(yaml_parser_t *parser, yaml_event_t *event)
247|{
248|    switch (parser->state)
249|    {
250|        case YAML_PARSE_STREAM_START_STATE:
251|            return yaml_parser_parse_stream_start(parser, event);
252|
253|        case YAML_PARSE_IMPLICIT_DOCUMENT_START_STATE:
254|            return yaml_parser_parse_document_start(parser, event, 1);
255|
256|        case YAML_PARSE_DOCUMENT_START_STATE:
257|            return yaml_parser_parse_document_start(parser, event, 0);
258|
259|        case YAML_PARSE_DOCUMENT_CONTENT_STATE:
260|            return yaml_parser_parse_document_content(parser, event);
261|
262|        case YAML_PARSE_DOCUMENT_END_STATE:
263|            return yaml_parser_parse_document_end(parser, event);
264|
265|        case YAML_PARSE_BLOCK_NODE_STATE:
266|            return yaml_parser_parse_node(parser, event, 1, 0);
267|
268|        case YAML_PARSE_BLOCK_NODE_OR_INDENTLESS_SEQUENCE_STATE:
269|            return yaml_parser_parse_node(parser, event, 1, 1);
270|
271|        case YAML_PARSE_FLOW_NODE_STATE:
272|            return yaml_parser_parse_node(parser, event, 0, 0);
273|
274|        case YAML_PARSE_BLOCK_SEQUENCE_FIRST_ENTRY_STATE:
275|            return yaml_parser_parse_block_sequence_entry(parser, event, 1);
276|
277|        case YAML_PARSE_BLOCK_SEQUENCE_ENTRY_STATE:
278|            return yaml_parser_parse_block_sequence_entry(parser, event, 0);
279|
280|        case YAML_PARSE_INDENTLESS_SEQUENCE_ENTRY_STATE:
281|            return yaml_parser_parse_indentless_sequence_entry(parser, event);
282|
283|        case YAML_PARSE_BLOCK_MAPPING_FIRST_KEY_STATE:
284|            return yaml_parser_parse_block_mapping_key(parser, event, 1);
285|
286|        case YAML_PARSE_BLOCK_MAPPING_KEY_STATE:
287|            return yaml_parser_parse_block_mapping_key(parser, event, 0);
288|
289|        case YAML_PARSE_BLOCK_MAPPING_VALUE_STATE:
290|            return yaml_parser_parse_block_mapping_value(parser, event);
291|
292|        case YAML_PARSE_FLOW_SEQUENCE_FIRST_ENTRY_STATE:
293|            return yaml_parser_parse_flow_sequence_entry(parser, event, 1);
294|
295|        case YAML_PARSE_FLOW_SEQUENCE_ENTRY_STATE:
296|            return yaml_parser_parse_flow_sequence_entry(parser, event, 0);
297|
298|        case YAML_PARSE_FLOW_SEQUENCE_ENTRY_MAPPING_KEY_STATE:
299|            return yaml_parser_parse_flow_sequence_entry_mapping_key(parser, event);
300|
301|        case YAML_PARSE_FLOW_SEQUENCE_ENTRY_MAPPING_VALUE_STATE:
302|            return yaml_parser_parse_flow_sequence_entry_mapping_value(parser, event);
303|
304|        case YAML_PARSE_FLOW_SEQUENCE_ENTRY_MAPPING_END_STATE:
305|            return yaml_parser_parse_flow_sequence_entry_mapping_end(parser, event);
306|
307|        case YAML_PARSE_FLOW_MAPPING_FIRST_KEY_STATE:
308|            return yaml_parser_parse_flow_mapping_key(parser, event, 1);
309|
310|        case YAML_PARSE_FLOW_MAPPING_KEY_STATE:
311|            return yaml_parser_parse_flow_mapping_key(parser, event, 0);
312|
313|        case YAML_PARSE_FLOW_MAPPING_VALUE_STATE:
314|            return yaml_parser_parse_flow_mapping_value(parser, event, 0);
315|
316|        case YAML_PARSE_FLOW_MAPPING_EMPTY_VALUE_STATE:
317|            return yaml_parser_parse_flow_mapping_value(parser, event, 1);
318|
319|        default:
320|            assert(1);      /* Invalid state. */
321|    }
322|
323|    return 0;
324|}
325|
326|/*
327| * Parse the production:
328| * stream   ::= STREAM-START implicit_document? explicit_document* STREAM-END
329| *              ************
330| */
331|
332|static int
333|yaml_parser_parse_stream_start(yaml_parser_t *parser, yaml_event_t *event)
334|{
335|    yaml_token_t *token;
336|
337|    token = PEEK_TOKEN(parser);
338|    if (!token) return 0;
339|
340|    if (token->type != YAML_STREAM_START_TOKEN) {
341|        return yaml_parser_set_parser_error(parser,
342|                "did not find expected <stream-start>", token->start_mark);
343|    }
344|
345|    parser->state = YAML_PARSE_IMPLICIT_DOCUMENT_START_STATE;
346|    STREAM_START_EVENT_INIT(*event, token->data.stream_start.encoding,
347|            token->start_mark, token->start_mark);
348|    SKIP_TOKEN(parser);
349|
350|    return 1;
351|}
352|
353|/*
354| * Parse the productions:
355| * implicit_document    ::= block_node DOCUMENT-END*
356| *                          *
357| * explicit_document    ::= DIRECTIVE* DOCUMENT-START block_node? DOCUMENT-END*
358| *                          *************************
359| */
360|
361|static int
362|yaml_parser_parse_document_start(yaml_parser_t *parser, yaml_event_t *event,
363|        int implicit)
364|{
365|    yaml_token_t *token;
366|    yaml_version_directive_t *version_directive = NULL;
367|    struct {
368|        yaml_tag_directive_t *start;
369|        yaml_tag_directive_t *end;
370|    } tag_directives = { NULL, NULL };
371|
372|    token = PEEK_TOKEN(parser);
373|    if (!token) return 0;
374|
375|    /* Parse extra document end indicators. */
376|
377|    if (!implicit)
378|    {
379|        while (token->type == YAML_DOCUMENT_END_TOKEN) {
380|            SKIP_TOKEN(parser);
381|            token = PEEK_TOKEN(parser);
382|            if (!token) return 0;
383|        }
384|    }
385|
386|    /* Parse an implicit document. */
387|
388|    if (implicit && token->type != YAML_VERSION_DIRECTIVE_TOKEN &&
389|            token->type != YAML_TAG_DIRECTIVE_TOKEN &&
390|            token->type != YAML_DOCUMENT_START_TOKEN &&
391|            token->type != YAML_STREAM_END_TOKEN)
392|    {
393|        if (!yaml_parser_process_directives(parser, NULL, NULL, NULL))
394|            return 0;
395|        if (!PUSH(parser, parser->states, YAML_PARSE_DOCUMENT_END_STATE))
396|            return 0;
397|        parser->state = YAML_PARSE_BLOCK_NODE_STATE;
398|        DOCUMENT_START_EVENT_INIT(*event, NULL, NULL, NULL, 1,
399|                token->start_mark, token->start_mark);
400|        return 1;
401|    }
402|
403|    /* Parse an explicit document. */
404|
405|    else if (token->type != YAML_STREAM_END_TOKEN)
406|    {
407|        yaml_mark_t start_mark, end_mark;
408|        start_mark = token->start_mark;
409|        if (!yaml_parser_process_directives(parser, &version_directive,
410|                    &tag_directives.start, &tag_directives.end))
411|            return 0;
412|        token = PEEK_TOKEN(parser);
413|        if (!token) goto error;
414|        if (token->type != YAML_DOCUMENT_START_TOKEN) {
415|            yaml_parser_set_parser_error(parser,
416|                    "did not find expected <document start>", token->start_mark);
417|            goto error;
418|        }
419|        if (!PUSH(parser, parser->states, YAML_PARSE_DOCUMENT_END_STATE))
420|            goto error;
421|        parser->state = YAML_PARSE_DOCUMENT_CONTENT_STATE;
422|        end_mark = token->end_mark;
423|        DOCUMENT_START_EVENT_INIT(*event, version_directive,
424|                tag_directives.start, tag_directives.end, 0,
425|                start_mark, end_mark);
426|        SKIP_TOKEN(parser);
427|        version_directive = NULL;
428|        tag_directives.start = tag_directives.end = NULL;
429|        return 1;
430|    }
431|
432|    /* Parse the stream end. */
433|
434|    else
435|    {
436|        parser->state = YAML_PARSE_END_STATE;
437|        STREAM_END_EVENT_INIT(*event, token->start_mark, token->end_mark);
438|        SKIP_TOKEN(parser);
439|        return 1;
440|    }
441|
442|error:
443|    yaml_free(version_directive);
444|    while (tag_directives.start != tag_directives.end) {
445|        yaml_free(tag_directives.end[-1].handle);
446|        yaml_free(tag_directives.end[-1].prefix);
447|        tag_directives.end --;
448|    }
449|    yaml_free(tag_directives.start);
450|    return 0;
451|}
452|
453|/*
454| * Parse the productions:
455| * explicit_document    ::= DIRECTIVE* DOCUMENT-START block_node? DOCUMENT-END*
456| *                                                    ***********
457| */
458|
459|static int
460|yaml_parser_parse_document_content(yaml_parser_t *parser, yaml_event_t *event)
461|{
462|    yaml_token_t *token;
463|
464|    token = PEEK_TOKEN(parser);
465|    if (!token) return 0;
466|
467|    if (token->type == YAML_VERSION_DIRECTIVE_TOKEN ||
468|            token->type == YAML_TAG_DIRECTIVE_TOKEN ||
469|            token->type == YAML_DOCUMENT_START_TOKEN ||
470|            token->type == YAML_DOCUMENT_END_TOKEN ||
471|            token->type == YAML_STREAM_END_TOKEN) {
472|        parser->state = POP(parser, parser->states);
473|        return yaml_parser_process_empty_scalar(parser, event,
474|                token->start_mark);
475|    }
476|    else {
477|        return yaml_parser_parse_node(parser, event, 1, 0);
478|    }
479|}
480|
481|/*
482| * Parse the productions:
483| * implicit_document    ::= block_node DOCUMENT-END*
484| *                                     *************
485| * explicit_document    ::= DIRECTIVE* DOCUMENT-START block_node? DOCUMENT-END*
486| *                                                                *************
487| */
488|
489|static int
490|yaml_parser_parse_document_end(yaml_parser_t *parser, yaml_event_t *event)
491|{
492|    yaml_token_t *token;
493|    yaml_mark_t start_mark, end_mark;
494|    int implicit = 1;
495|
496|    token = PEEK_TOKEN(parser);
497|    if (!token) return 0;
498|
499|    start_mark = end_mark = token->start_mark;
500|
501|    if (token->type == YAML_DOCUMENT_END_TOKEN) {
502|        end_mark = token->end_mark;
503|        SKIP_TOKEN(parser);
504|        implicit = 0;
505|    }
506|
507|    while (!STACK_EMPTY(parser, parser->tag_directives)) {
508|        yaml_tag_directive_t tag_directive = POP(parser, parser->tag_directives);
509|        yaml_free(tag_directive.handle);
510|        yaml_free(tag_directive.prefix);
511|    }
512|
513|    parser->state = YAML_PARSE_DOCUMENT_START_STATE;
514|    DOCUMENT_END_EVENT_INIT(*event, implicit, start_mark, end_mark);
515|
516|    return 1;
517|}
518|
519|/*
520| * Parse the productions:
521| * block_node_or_indentless_sequence    ::=
522| *                          ALIAS
523| *                          *****
524| *                          | properties (block_content | indentless_block_sequence)?
525| *                            **********  *
526| *                          | block_content | indentless_block_sequence
527| *                            *
528| * block_node           ::= ALIAS
529| *                          *****
530| *                          | properties block_content?
531| *                            ********** *
532| *                          | block_content
533| *                            *
534| * flow_node            ::= ALIAS
535| *                          *****
536| *                          | properties flow_content?
537| *                            ********** *
538| *                          | flow_content
539| *                            *
540| * properties           ::= TAG ANCHOR? | ANCHOR TAG?
541| *                          *************************
542| * block_content        ::= block_collection | flow_collection | SCALAR
543| *                                                               ******
544| * flow_content         ::= flow_collection | SCALAR
545| *                                            ******
546| */
547|
548|static int
549|yaml_parser_parse_node(yaml_parser_t *parser, yaml_event_t *event,
550|        int block, int indentless_sequence)
551|{
552|    yaml_token_t *token;
553|    yaml_char_t *anchor = NULL;
554|    yaml_char_t *tag_handle = NULL;
555|    yaml_char_t *tag_suffix = NULL;
556|    yaml_char_t *tag = NULL;
557|    yaml_mark_t start_mark, end_mark, tag_mark;
558|    int implicit;
559|
560|    token = PEEK_TOKEN(parser);
561|    if (!token) return 0;
562|
563|    if (token->type == YAML_ALIAS_TOKEN)
564|    {
565|        parser->state = POP(parser, parser->states);
566|        ALIAS_EVENT_INIT(*event, token->data.alias.value,
567|                token->start_mark, token->end_mark);
568|        SKIP_TOKEN(parser);
569|        return 1;
570|    }
571|
572|    else
573|    {
574|        start_mark = end_mark = token->start_mark;
575|
576|        if (token->type == YAML_ANCHOR_TOKEN)
577|        {
578|            anchor = token->data.anchor.value;
579|            start_mark = token->start_mark;
580|            end_mark = token->end_mark;
581|            SKIP_TOKEN(parser);
582|            token = PEEK_TOKEN(parser);
583|            if (!token) goto error;
584|            if (token->type == YAML_TAG_TOKEN)
585|            {
586|                tag_handle = token->data.tag.handle;
587|                tag_suffix = token->data.tag.suffix;
588|                tag_mark = token->start_mark;
589|                end_mark = token->end_mark;
590|                SKIP_TOKEN(parser);
591|                token = PEEK_TOKEN(parser);
592|                if (!token) goto error;
593|            }
594|        }
595|        else if (token->type == YAML_TAG_TOKEN)
596|        {
597|            tag_handle = token->data.tag.handle;
598|            tag_suffix = token->data.tag.suffix;
599|            start_mark = tag_mark = token->start_mark;
600|            end_mark = token->end_mark;
601|            SKIP_TOKEN(parser);
602|            token = PEEK_TOKEN(parser);
603|            if (!token) goto error;
604|            if (token->type == YAML_ANCHOR_TOKEN)
605|            {
606|                anchor = token->data.anchor.value;
607|                end_mark = token->end_mark;
608|                SKIP_TOKEN(parser);
609|                token = PEEK_TOKEN(parser);
610|                if (!token) goto error;
611|            }
612|        }
613|
614|        if (tag_handle) {
615|            if (!*tag_handle) {
616|                tag = tag_suffix;
617|                yaml_free(tag_handle);
618|                tag_handle = tag_suffix = NULL;
619|            }
620|            else {
621|                yaml_tag_directive_t *tag_directive;
622|                for (tag_directive = parser->tag_directives.start;
623|                        tag_directive != parser->tag_directives.top;
624|                        tag_directive ++) {
625|                    if (strcmp((char *)tag_directive->handle, (char *)tag_handle) == 0) {
626|                        size_t prefix_len = strlen((char *)tag_directive->prefix);
627|                        size_t suffix_len = strlen((char *)tag_suffix);
628|                        tag = YAML_MALLOC(prefix_len+suffix_len+1);
629|                        if (!tag) {
630|                            parser->error = YAML_MEMORY_ERROR;
631|                            goto error;
632|                        }
633|                        memcpy(tag, tag_directive->prefix, prefix_len);
634|                        memcpy(tag+prefix_len, tag_suffix, suffix_len);
635|                        tag[prefix_len+suffix_len] = '\0';
636|                        yaml_free(tag_handle);
637|                        yaml_free(tag_suffix);
638|                        tag_handle = tag_suffix = NULL;
639|                        break;
640|                    }
641|                }
642|                if (!tag) {
643|                    yaml_parser_set_parser_error_context(parser,
644|                            "while parsing a node", start_mark,
645|                            "found undefined tag handle", tag_mark);
646|                    goto error;
647|                }
648|            }
649|        }
650|
651|        implicit = (!tag || !*tag);
652|        if (indentless_sequence && token->type == YAML_BLOCK_ENTRY_TOKEN) {
653|            end_mark = token->end_mark;
654|            parser->state = YAML_PARSE_INDENTLESS_SEQUENCE_ENTRY_STATE;
655|            SEQUENCE_START_EVENT_INIT(*event, anchor, tag, implicit,
656|                    YAML_BLOCK_SEQUENCE_STYLE, start_mark, end_mark);
657|            return 1;
658|        }
659|        else {
660|            if (token->type == YAML_SCALAR_TOKEN) {
661|                int plain_implicit = 0;
662|                int quoted_implicit = 0;
663|                end_mark = token->end_mark;
664|                if ((token->data.scalar.style == YAML_PLAIN_SCALAR_STYLE && !tag)
665|                        || (tag && strcmp((char *)tag, "!") == 0)) {
666|                    plain_implicit = 1;
667|                }
668|                else if (!tag) {
669|                    quoted_implicit = 1;
670|                }
671|                parser->state = POP(parser, parser->states);
672|                SCALAR_EVENT_INIT(*event, anchor, tag,
673|                        token->data.scalar.value, token->data.scalar.length,
674|                        plain_implicit, quoted_implicit,
675|                        token->data.scalar.style, start_mark, end_mark);
676|                SKIP_TOKEN(parser);
677|                return 1;
678|            }
679|            else if (token->type == YAML_FLOW_SEQUENCE_START_TOKEN) {
680|                if (!STACK_LIMIT(parser, parser->indents, MAX_NESTING_LEVEL - parser->flow_level)) {
681|                    yaml_maximum_level_reached(parser, start_mark, token->start_mark);
682|                    goto error;
683|                }
684|                end_mark = token->end_mark;
685|                parser->state = YAML_PARSE_FLOW_SEQUENCE_FIRST_ENTRY_STATE;
686|                SEQUENCE_START_EVENT_INIT(*event, anchor, tag, implicit,
687|                        YAML_FLOW_SEQUENCE_STYLE, start_mark, end_mark);
688|                return 1;
689|            }
690|            else if (token->type == YAML_FLOW_MAPPING_START_TOKEN) {
691|                if (!STACK_LIMIT(parser, parser->indents, MAX_NESTING_LEVEL - parser->flow_level)) {
692|                    yaml_maximum_level_reached(parser, start_mark, token->start_mark);
693|                    goto error;
694|                }
695|                end_mark = token->end_mark;
696|                parser->state = YAML_PARSE_FLOW_MAPPING_FIRST_KEY_STATE;
697|                MAPPING_START_EVENT_INIT(*event, anchor, tag, implicit,
698|                        YAML_FLOW_MAPPING_STYLE, start_mark, end_mark);
699|                return 1;
700|            }
701|            else if (block && token->type == YAML_BLOCK_SEQUENCE_START_TOKEN) {
702|                if (!STACK_LIMIT(parser, parser->indents, MAX_NESTING_LEVEL - parser->flow_level)) {
703|                    yaml_maximum_level_reached(parser, start_mark, token->start_mark);
704|                    goto error;
705|                }
706|                end_mark = token->end_mark;
707|                parser->state = YAML_PARSE_BLOCK_SEQUENCE_FIRST_ENTRY_STATE;
708|                SEQUENCE_START_EVENT_INIT(*event, anchor, tag, implicit,
709|                        YAML_BLOCK_SEQUENCE_STYLE, start_mark, end_mark);
710|                return 1;
711|            }
712|            else if (block && token->type == YAML_BLOCK_MAPPING_START_TOKEN) {
713|                if (!STACK_LIMIT(parser, parser->indents, MAX_NESTING_LEVEL - parser->flow_level)) {
714|                    yaml_maximum_level_reached(parser, start_mark, token->start_mark);
715|                    goto error;
716|                }
717|                end_mark = token->end_mark;
718|                parser->state = YAML_PARSE_BLOCK_MAPPING_FIRST_KEY_STATE;
719|                MAPPING_START_EVENT_INIT(*event, anchor, tag, implicit,
720|                        YAML_BLOCK_MAPPING_STYLE, start_mark, end_mark);
721|                return 1;
722|            }
723|            else if (anchor || tag) {
724|                yaml_char_t *value = YAML_MALLOC(1);
725|                if (!value) {
726|                    parser->error = YAML_MEMORY_ERROR;
727|                    goto error;
728|                }
729|                value[0] = '\0';
730|                parser->state = POP(parser, parser->states);
731|                SCALAR_EVENT_INIT(*event, anchor, tag, value, 0,
732|                        implicit, 0, YAML_PLAIN_SCALAR_STYLE,
733|                        start_mark, end_mark);
734|                return 1;
735|            }
736|            else {
737|                yaml_parser_set_parser_error_context(parser,
738|                        (block ? "while parsing a block node"
739|                         : "while parsing a flow node"), start_mark,
740|                        "did not find expected node content", token->start_mark);
741|                goto error;
742|            }
743|        }
744|    }
745|
746|error:
747|    yaml_free(anchor);
748|    yaml_free(tag_handle);
749|    yaml_free(tag_suffix);
750|    yaml_free(tag);
751|
752|    return 0;
753|}
754|
755|/*
756| * Parse the productions:
757| * block_sequence ::= BLOCK-SEQUENCE-START (BLOCK-ENTRY block_node?)* BLOCK-END
758| *                    ********************  *********** *             *********
759| */
760|
761|static int
762|yaml_parser_parse_block_sequence_entry(yaml_parser_t *parser,
763|        yaml_event_t *event, int first)
764|{
765|    yaml_token_t *token;
766|
767|    if (first) {
768|        token = PEEK_TOKEN(parser);
769|        if (!PUSH(parser, parser->marks, token->start_mark))
770|            return 0;
771|        SKIP_TOKEN(parser);
772|    }
773|
774|    token = PEEK_TOKEN(parser);
775|    if (!token) return 0;
776|
777|    if (token->type == YAML_BLOCK_ENTRY_TOKEN)
778|    {
779|        yaml_mark_t mark = token->end_mark;
780|        SKIP_TOKEN(parser);
781|        token = PEEK_TOKEN(parser);
782|        if (!token) return 0;
783|        if (token->type != YAML_BLOCK_ENTRY_TOKEN &&
784|                token->type != YAML_BLOCK_END_TOKEN) {
785|            if (!PUSH(parser, parser->states,
786|                        YAML_PARSE_BLOCK_SEQUENCE_ENTRY_STATE))
787|                return 0;
788|            return yaml_parser_parse_node(parser, event, 1, 0);
789|        }
790|        else {
791|            parser->state = YAML_PARSE_BLOCK_SEQUENCE_ENTRY_STATE;
792|            return yaml_parser_process_empty_scalar(parser, event, mark);
793|        }
794|    }
795|
796|    else if (token->type == YAML_BLOCK_END_TOKEN)
797|    {
798|        parser->state = POP(parser, parser->states);
799|        (void)POP(parser, parser->marks);
800|        SEQUENCE_END_EVENT_INIT(*event, token->start_mark, token->end_mark);
801|        SKIP_TOKEN(parser);
802|        return 1;
803|    }
804|
805|    else
806|    {
807|        return yaml_parser_set_parser_error_context(parser,
808|                "while parsing a block collection", POP(parser, parser->marks),
809|                "did not find expected '-' indicator", token->start_mark);
810|    }
811|}
812|
813|/*
814| * Parse the productions:
815| * indentless_sequence  ::= (BLOCK-ENTRY block_node?)+
816| *                           *********** *
817| */
818|
819|static int
820|yaml_parser_parse_indentless_sequence_entry(yaml_parser_t *parser,
821|        yaml_event_t *event)
822|{
823|    yaml_token_t *token;
824|
825|    token = PEEK_TOKEN(parser);
826|    if (!token) return 0;
827|
828|    if (token->type == YAML_BLOCK_ENTRY_TOKEN)
829|    {
830|        yaml_mark_t mark = token->end_mark;
831|        SKIP_TOKEN(parser);
832|        token = PEEK_TOKEN(parser);
833|        if (!token) return 0;
834|        if (token->type != YAML_BLOCK_ENTRY_TOKEN &&
835|                token->type != YAML_KEY_TOKEN &&
836|                token->type != YAML_VALUE_TOKEN &&
837|                token->type != YAML_BLOCK_END_TOKEN) {
838|            if (!PUSH(parser, parser->states,
839|                        YAML_PARSE_INDENTLESS_SEQUENCE_ENTRY_STATE))
