846|        }
847|    }
848|
849|    else
850|    {
851|        parser->state = POP(parser, parser->states);
852|        SEQUENCE_END_EVENT_INIT(*event, token->start_mark, token->start_mark);
853|        return 1;
854|    }
855|}
