917|                "while parsing a block mapping", POP(parser, parser->marks),
918|                "did not find expected key", token->start_mark);
919|    }
920|}
921|
922|/*
923| * Parse the productions:
924| * block_mapping        ::= BLOCK-MAPPING_START
925| *
926| *                          ((KEY block_node_or_indentless_sequence?)?
927| *
928| *                          (VALUE block_node_or_indentless_sequence?)?)*
929| *                           ***** *
930| *                          BLOCK-END
931| *
932| */
933|
