1265|/*
1266| * Parse directives.
1267| */
1268|
1269|static int
1270|yaml_parser_process_directives(yaml_parser_t *parser,
1271|        yaml_version_directive_t **version_directive_ref,
1272|        yaml_tag_directive_t **tag_directives_start_ref,
1273|        yaml_tag_directive_t **tag_directives_end_ref)
1274|{
1275|    yaml_tag_directive_t default_tag_directives[] = {
1276|        {(yaml_char_t *)"!", (yaml_char_t *)"!"},
1277|        {(yaml_char_t *)"!!", (yaml_char_t *)"tag:yaml.org,2002:"},
1278|        {NULL, NULL}
1279|    };
1280|    yaml_tag_directive_t *default_tag_directive;
1281|    yaml_version_directive_t *version_directive = NULL;
1282|    struct {
1283|        yaml_tag_directive_t *start;
1284|        yaml_tag_directive_t *end;
1285|        yaml_tag_directive_t *top;
1286|    } tag_directives = { NULL, NULL, NULL };
1287|    yaml_token_t *token;
1288|
1289|    if (!STACK_INIT(parser, tag_directives, yaml_tag_directive_t*))
1290|        goto error;
1291|
1292|    token = PEEK_TOKEN(parser);
1293|    if (!token) goto error;
1294|
1295|    while (token->type == YAML_VERSION_DIRECTIVE_TOKEN ||
1296|            token->type == YAML_TAG_DIRECTIVE_TOKEN)
1297|    {
1298|        if (token->type == YAML_VERSION_DIRECTIVE_TOKEN) {
1299|            if (version_directive) {
1300|                yaml_parser_set_parser_error(parser,
1301|                        "found duplicate %YAML directive", token->start_mark);
1302|                goto error;
1303|            }
1304|            if (token->data.version_directive.major != 1
1305|                    || (
1306|                        token->data.version_directive.minor != 1
1307|                        && token->data.version_directive.minor != 2
1308|                    )) {
1309|                yaml_parser_set_parser_error(parser,
1310|                        "found incompatible YAML document", token->start_mark);
1311|                goto error;
1312|            }
1313|            version_directive = YAML_MALLOC_STATIC(yaml_version_directive_t);
1314|            if (!version_directive) {
1315|                parser->error = YAML_MEMORY_ERROR;
1316|                goto error;
1317|            }
1318|            version_directive->major = token->data.version_directive.major;
1319|            version_directive->minor = token->data.version_directive.minor;
1320|        }
1321|
1322|        else if (token->type == YAML_TAG_DIRECTIVE_TOKEN) {
1323|            yaml_tag_directive_t value;
1324|            value.handle = token->data.tag_directive.handle;
1325|            value.prefix = token->data.tag_directive.prefix;
1326|
1327|            if (!yaml_parser_append_tag_directive(parser, value, 0,
1328|                        token->start_mark))
1329|                goto error;
1330|            if (!PUSH(parser, tag_directives, value))
1331|                goto error;
1332|        }
1333|
1334|        SKIP_TOKEN(parser);
1335|        token = PEEK_TOKEN(parser);
1336|        if (!token) goto error;
1337|    }
1338|
1339|    for (default_tag_directive = default_tag_directives;
1340|            default_tag_directive->handle; default_tag_directive++) {
1341|        if (!yaml_parser_append_tag_directive(parser, *default_tag_directive, 1,
1342|                    token->start_mark))
1343|            goto error;
1344|    }
1345|
1346|    if (version_directive_ref) {
1347|        *version_directive_ref = version_directive;
1348|    }
1349|    if (tag_directives_start_ref) {
1350|        if (STACK_EMPTY(parser, tag_directives)) {
1351|            *tag_directives_start_ref = *tag_directives_end_ref = NULL;
1352|            STACK_DEL(parser, tag_directives);
1353|        }
1354|        else {
1355|            *tag_directives_start_ref = tag_directives.start;
1356|            *tag_directives_end_ref = tag_directives.top;
1357|        }
1358|    }
1359|    else {
1360|        STACK_DEL(parser, tag_directives);
1361|    }
1362|
1363|    if (!version_directive_ref)
1364|        yaml_free(version_directive);
1365|    return 1;
1366|
1367|error:
1368|    yaml_free(version_directive);
1369|    while (!STACK_EMPTY(parser, tag_directives)) {
1370|        yaml_tag_directive_t tag_directive = POP(parser, tag_directives);
1371|        yaml_free(tag_directive.handle);
1372|        yaml_free(tag_directive.prefix);
1373|    }
1374|    STACK_DEL(parser, tag_directives);
1375|    return 0;
1376|}
