241|/*
242| * State dispatcher.
243| */
244|
245|static int
246|yaml_parser_state_machine(yaml_parser_t *parser, yaml_event_t *event)
247|{
248|    switch (parser->state)
249|    {
250|        case YAML_PARSE_STREAM_START_STATE:
251|            return yaml_parser_parse_stream_start(parser, event);
252|
253|        case YAML_PARSE_IMPLICIT_DOCUMENT_START_STATE:
254|            return yaml_parser_parse_document_start(parser, event, 1);
255|
256|        case YAML_PARSE_DOCUMENT_START_STATE:
257|            return yaml_parser_parse_document_start(parser, event, 0);
258|
259|        case YAML_PARSE_DOCUMENT_CONTENT_STATE:
260|            return yaml_parser_parse_document_content(parser, event);
261|
262|        case YAML_PARSE_DOCUMENT_END_STATE:
263|            return yaml_parser_parse_document_end(parser, event);
264|
265|        case YAML_PARSE_BLOCK_NODE_STATE:
266|            return yaml_parser_parse_node(parser, event, 1, 0);
267|
268|        case YAML_PARSE_BLOCK_NODE_OR_INDENTLESS_SEQUENCE_STATE:
269|            return yaml_parser_parse_node(parser, event, 1, 1);
270|
271|        case YAML_PARSE_FLOW_NODE_STATE:
272|            return yaml_parser_parse_node(parser, event, 0, 0);
273|
274|        case YAML_PARSE_BLOCK_SEQUENCE_FIRST_ENTRY_STATE:
275|            return yaml_parser_parse_block_sequence_entry(parser, event, 1);
276|
277|        case YAML_PARSE_BLOCK_SEQUENCE_ENTRY_STATE:
278|            return yaml_parser_parse_block_sequence_entry(parser, event, 0);
279|
280|        case YAML_PARSE_INDENTLESS_SEQUENCE_ENTRY_STATE:
281|            return yaml_parser_parse_indentless_sequence_entry(parser, event);
282|
283|        case YAML_PARSE_BLOCK_MAPPING_FIRST_KEY_STATE:
284|            return yaml_parser_parse_block_mapping_key(parser, event, 1);
285|
286|        case YAML_PARSE_BLOCK_MAPPING_KEY_STATE:
287|            return yaml_parser_parse_block_mapping_key(parser, event, 0);
288|
289|        case YAML_PARSE_BLOCK_MAPPING_VALUE_STATE:
290|            return yaml_parser_parse_block_mapping_value(parser, event);
291|
292|        case YAML_PARSE_FLOW_SEQUENCE_FIRST_ENTRY_STATE:
293|            return yaml_parser_parse_flow_sequence_entry(parser, event, 1);
294|
295|        case YAML_PARSE_FLOW_SEQUENCE_ENTRY_STATE:
296|            return yaml_parser_parse_flow_sequence_entry(parser, event, 0);
297|
298|        case YAML_PARSE_FLOW_SEQUENCE_ENTRY_MAPPING_KEY_STATE:
299|            return yaml_parser_parse_flow_sequence_entry_mapping_key(parser, event);
300|
301|        case YAML_PARSE_FLOW_SEQUENCE_ENTRY_MAPPING_VALUE_STATE:
302|            return yaml_parser_parse_flow_sequence_entry_mapping_value(parser, event);
303|
304|        case YAML_PARSE_FLOW_SEQUENCE_ENTRY_MAPPING_END_STATE:
305|            return yaml_parser_parse_flow_sequence_entry_mapping_end(parser, event);
306|
307|        case YAML_PARSE_FLOW_MAPPING_FIRST_KEY_STATE:
308|            return yaml_parser_parse_flow_mapping_key(parser, event, 1);
309|
310|        case YAML_PARSE_FLOW_MAPPING_KEY_STATE:
311|            return yaml_parser_parse_flow_mapping_key(parser, event, 0);
312|
313|        case YAML_PARSE_FLOW_MAPPING_VALUE_STATE:
314|            return yaml_parser_parse_flow_mapping_value(parser, event, 0);
315|
316|        case YAML_PARSE_FLOW_MAPPING_EMPTY_VALUE_STATE:
317|            return yaml_parser_parse_flow_mapping_value(parser, event, 1);
318|
319|        default:
320|            assert(1);      /* Invalid state. */
321|    }
322|
323|    return 0;
324|}
